static int cmp_id(const void *k, const void *e)
{
    return strcmp((const char *)k, ((const Name4u *)e)->id);
}

const char *dlc_4u_name_en(const char *ascii_id)
{
    if (!ascii_id || !ascii_id[0]) return NULL;
    const Name4u *hit = bsearch(ascii_id, NAMES_4U,
                                sizeof NAMES_4U / sizeof NAMES_4U[0],
                                sizeof NAMES_4U[0], cmp_id);
    return hit ? hit->en : NULL;
}
